def unique_characters_in_order(text: str) -> str:
    seen = ''
    for ch in text:
        if ch not in seen:
            seen += ch
    return seen

def alternating_case_start_upper(text: str) -> str:
    result = ''
    for i, ch in enumerate(text):
        result += ch.upper() if i % 2 == 0 else ch.lower()
    return result

def alternating_case_start_lower(text: str) -> str:
    result = ''
    for i, ch in enumerate(text):
        result += ch.lower() if i % 2 == 0 else ch.upper()
    return result

def remove_punctuation_basic(text: str) -> str:
    chars = ',.!?;:'
    return ''.join(ch for ch in text if ch not in chars)

def longest_word(text: str) -> str:
    words = text.split()
    return max(words, key=len) if words else ''

def shortest_word(text: str) -> str:
    words = text.split()
    return min(words, key=len) if words else ''

def first_word(text: str) -> str:
    parts = text.split()
    return parts[0] if parts else ''

def last_word(text: str) -> str:
    parts = text.split()
    return parts[-1] if parts else ''

def remove_duplicate_spaces(text: str) -> str:
    while '  ' in text:
        text = text.replace('  ', ' ')
    return text

def rot13_lowercase_only(text: str) -> str:
    result = ''
    for ch in text:
        if 'a' <= ch <= 'z':
            result += chr((ord(ch) - 97 + 13) % 26 + 97)
        else:
            result += ch
    return result

def shift_letters_by_one(text: str) -> str:
    result = ''
    for ch in text:
        if 'a' <= ch <= 'z':
            result += chr((ord(ch) - 97 + 1) % 26 + 97)
        elif 'A' <= ch <= 'Z':
            result += chr((ord(ch) - 65 + 1) % 26 + 65)
        else:
            result += ch
    return result

def shift_digits_by_one(text: str) -> str:
    result = ''
    for ch in text:
        if ch.isdigit():
            result += str((int(ch) + 1) % 10)
        else:
            result += ch
    return result

def number_words(text: str) -> str:
    words = text.split()
    return ' '.join(str(i + 1) + ':' + word for i, word in enumerate(words))

def outer_characters(text: str) -> str:
    if not text:
        return ''
    return text[:1] + text[-1:]

def remove_surrounding_quotes(text: str) -> str:
    if len(text) >= 2 and text[0] == text[-1] and text[0] in "'\"":
        return text[1:-1]
    return text

def split_camel_like_boundaries(text: str) -> str:
    result = ''
    for i, ch in enumerate(text):
        if i and ch.isupper():
            result += ' '
        result += ch
    return result
